frappe.ui.form.on('Employee', {
    employment_type: function(frm) {
        if (frm.doc.employment_type === 'Contract') {
            frm.set_value('custom_contract', 1);
            frm.set_value('custom_regular', 0);
        } else if (frm.doc.employment_type === 'Full-time' || frm.doc.employment_type === 'Probation') {
            frm.set_value('custom_contract', 0);
            frm.set_value('custom_regular', 1);
        } else {
            // Optional: Handle other employment types if needed
            frm.set_value('custom_contract', 0);
            frm.set_value('custom_regular', 0);
        }
    },

    custom_contract: function(frm) {
        if (frm.doc.custom_contract) {
            frm.set_value('employment_type', 'Contract');
            frm.set_value('custom_regular', 0); // Ensure only one custom field is true
        } else {
             // If custom_contract is unchecked, you might want to clear employment_type or set a default
             // Depending on your business logic, you might not want to clear if custom_regular is true
             if (!frm.doc.custom_regular) {
                 frm.set_value('employment_type', ''); // Or a default value if applicable
             }
        }
    },

    custom_regular: function(frm) {
        if (frm.doc.custom_regular) {
            frm.set_value('employment_type', 'Full-time');
            frm.set_value('custom_contract', 0); // Ensure only one custom field is true
        } else {
            // If custom_regular is unchecked, you might want to clear employment_type or set a default
            // Depending on your business logic, you might not want to clear if custom_contract is true
            if (!frm.doc.custom_contract) {
                frm.set_value('employment_type', ''); // Or a default value if applicable
            }
        }
    }
});

