frappe.ui.form.on('Employee External Work History', {
    custom_to_date: function(frm, cdt, cdn) {
        const child_row = locals[cdt][cdn];
        
        // Only calculate if both dates exist
        if (!child_row.custom_from_date || !child_row.custom_to_date) {
            frappe.model.set_value(cdt, cdn, 'total_experience', null);
            return;
        }

        const from_date = new Date(child_row.custom_from_date);
        const to_date = new Date(child_row.custom_to_date);

        // Validate date order
        if (from_date > to_date) {
            frappe.msgprint(__('End date must be after start date'));
            frappe.model.set_value(cdt, cdn, 'total_experience', 'Invalid date range');
            return;
        }

        // Calculate months difference
        let months = (to_date.getFullYear() - from_date.getFullYear()) * 12;
        months += to_date.getMonth() - from_date.getMonth();
        
        // Adjust for day difference
        if (to_date.getDate() < from_date.getDate()) {
            months--;
        }

        // Convert to years and months
        const years = Math.floor(months / 12);
        const remaining_months = months % 12;

        // Format the result
        let experience = '';
        if (years > 0) experience += `${years} year${years !== 1 ? 's' : ''}`;
        if (remaining_months > 0) {
            if (experience) experience += ' ';
            experience += `${remaining_months} month${remaining_months !== 1 ? 's' : ''}`;
        }

        // Set the calculated value
        frappe.model.set_value(cdt, cdn, 'total_experience', experience || '0 months');
    }
});

