});

frappe.ui.form.on('Employee Efficiency', {
    // Trigger the calculation when first_half_result is updated
    first_half_result: function(frm) {
        update_average(frm);
    },
    // Trigger the calculation when second_half_result is updated
    second_half_result: function(frm) {
        update_average(frm);
    }
});

// Function to calculate average
function update_average(frm) {
    let first = frm.doc.first_half_result || 0;
    let second = frm.doc.second_half_result || 0;

    // Calculate average. If both values are numbers, the average will be computed.
    let avg = (first + second) / 2;

    // Set the average field with the calculated value
    frm.set_value('average', avg);
}

